//! Gauss quadrature generated by native tridiagonal eigenanalysis.
use super::{EigenValuesSearcher, ValueAndWeight, Vector};
use rustycad_tkernel::{ncollection::Array1, standard::Failure};

/// Computed quadrature nodes and weights; `GaussPointsAndWeights::new(125)?`.
pub struct GaussPointsAndWeights {
    points: Vector<'static>,
    weights: Vector<'static>,
    done: bool,
}
impl GaussPointsAndWeights {
    /// Computes n nodes on [-1,1]; `GaussPointsAndWeights::new(7)?`.
    pub fn new(order: i32) -> Result<Self, Failure> {
        // A negative order corrupts the heap natively; zero builds empty arrays and
        // an eigen search that is not done, which the general path reproduces.
        if order < 0 {
            return Err(Failure::out_of_range(&format!(
                "Gauss order {order}; expected a non-negative order"
            )));
        }
        let size: i32 = order;
        let mut diagonal: Array1<'static, f64> = Array1::with_bounds(1, size).unwrap();
        let mut subdiagonal: Array1<'static, f64> = Array1::with_bounds(1, size).unwrap();
        for index in 1..=size {
            diagonal[index] = 0.0;
            subdiagonal[index] = if index == 1 {
                0.0
            } else {
                let square: i32 = (index - 1) * (index - 1);
                (f64::from(square) / (4.0 * f64::from(square) - 1.0)).sqrt()
            };
        }
        let mut result: Self = Self {
            points: Vector::with_bounds(1, size)?,
            weights: Vector::with_bounds(1, size)?,
            done: false,
        };
        // The native constructor catches every Standard_Failure and stays not done.
        let Ok(eigensolver) = EigenValuesSearcher::new(&diagonal, &subdiagonal) else {
            return Ok(result);
        };
        if eigensolver.is_done() {
            result.collect(&eigensolver)?;
        }
        Ok(result)
    }
    fn collect(&mut self, eigensolver: &EigenValuesSearcher) -> Result<(), Failure> {
        sorted_nodes(eigensolver, &mut self.points, &mut self.weights)?;
        self.done = true;
        Ok(())
    }
    /// Reports convergence of the Gauss eigenproblem; `quadrature.is_done()`.
    pub fn is_done(&self) -> bool {
        self.done
    }
    /// Copies ascending nodes with one-based bounds; `quadrature.points()`.
    pub fn points(&self) -> Vector<'static> {
        self.points.clone()
    }
    /// Copies the corresponding quadrature weights; `quadrature.weights()`.
    pub fn weights(&self) -> Vector<'static> {
        self.weights.clone()
    }
}

/// Nodes are the eigenvalues and weights twice the squared first eigenvector entries,
/// sorted by node through math_ValueAndWeight as both native constructors do.
pub(super) fn sorted_nodes(
    eigensolver: &EigenValuesSearcher,
    points: &mut Vector<'_>,
    weights: &mut Vector<'_>,
) -> Result<(), Failure> {
    let mut nodes: Vec<ValueAndWeight> = Vec::with_capacity(eigensolver.dimension() as usize);
    for index in 1..=eigensolver.dimension() {
        let first: f64 = eigensolver.eigen_vector(index)?[1];
        nodes.push(ValueAndWeight::new(
            eigensolver.eigen_value(index)?,
            2.0 * first * first,
        ));
    }
    ValueAndWeight::sort(&mut nodes);
    for (offset, node) in nodes.iter().enumerate() {
        points[offset as i32 + 1] = node.value();
        weights[offset as i32 + 1] = node.weight();
    }
    Ok(())
}
